'use strict';

var a11y = require('@lexical/a11y');
var extension = require('@lexical/extension');
var LexicalComposerContext = require('@lexical/react/LexicalComposerContext');
var react = require('react');

/**
 * Copyright (c) Meta Platforms, Inc. and affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 *
 */


/**
 * Returns a stable `announce` function backed by the editor's
 * {@link AriaLiveRegionExtension} output. Requires
 * `AriaLiveRegionExtension` in the editor's extension tree.
 */
function useLexicalAriaLiveRegion() {
  const [editor] = LexicalComposerContext.useLexicalComposerContext();
  return react.useCallback(message => {
    const dep = extension.getExtensionDependencyFromEditor(editor, a11y.AriaLiveRegionExtension);
    dep.output.announce(message);
  }, [editor]);
}

exports.useLexicalAriaLiveRegion = useLexicalAriaLiveRegion;
